#pragma once
#include "HostIPCScope.h"
#include <fstream>

namespace coincide::background_host {
// One atomic private checkpoint. This is a bounded correctness foundation, not a high-rate
// append-only database. UI workspace/index/transcript files are never opened by this class.
class Ledger {
    const Scope& scope_;Object original_{nullptr};std::optional<std::string> snapshot_;std::size_t maximum_;
    std::filesystem::path file()const{return scope_.ledger_directory()/L"runtime.json";}
    static void structure(const winrt::Windows::Data::Json::IJsonValue& value,unsigned depth=0,std::size_t* count=nullptr){std::size_t local{};if(!count)count=&local;if(depth>16||++*count>250000)throw std::invalid_argument("The private host ledger exceeds its structural bound");if(value.ValueType()==Type::Object){for(const auto& item:value.GetObject()){if(item.Key().size()>128)throw std::invalid_argument("Host ledger key exceeds its bound");structure(item.Value(),depth+1,count);}}else if(value.ValueType()==Type::Array){if(value.GetArray().Size()>10000)throw std::invalid_argument("Host ledger array exceeds its bound");for(const auto& item:value.GetArray())structure(item,depth+1,count);}else if(value.ValueType()==Type::String){const auto bytes=winrt::to_string(value.GetString());if(bytes.size()>2*1024*1024||bytes.find('\0')!=std::string::npos)throw std::invalid_argument("Host ledger value exceeds its bound");}else if(value.ValueType()==Type::Number&&!std::isfinite(value.GetNumber()))throw std::invalid_argument("Invalid host ledger number");}
    std::optional<std::string> read()const{if(!std::filesystem::exists(file()))return{};Handle handle(CreateFileW(file().c_str(),GENERIC_READ|READ_CONTROL,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_FLAG_OPEN_REPARSE_POINT,nullptr));BY_HANDLE_FILE_INFORMATION info{};if(!handle||!GetFileInformationByHandle(handle.value,&info)||(info.dwFileAttributes&(FILE_ATTRIBUTE_DIRECTORY|FILE_ATTRIBUTE_REPARSE_POINT))||info.nNumberOfLinks!=1)throw std::runtime_error("The private host ledger is unavailable or linked");verify_security(handle.value,scope_.sid(),SE_FILE_OBJECT);const auto size=(static_cast<std::uint64_t>(info.nFileSizeHigh)<<32)|info.nFileSizeLow;if(size>maximum_)throw std::runtime_error("The private host ledger exceeds its file size limit");std::string bytes(static_cast<std::size_t>(size),'\0');DWORD copied{};if(size&&(!ReadFile(handle.value,bytes.data(),static_cast<DWORD>(size),&copied,nullptr)||copied!=size))throw std::runtime_error("Could not read the complete private host ledger");if(!local_file::utf8(bytes))throw std::runtime_error("The private host ledger is not UTF-8");return bytes;}
public:
    explicit Ledger(const Scope& scope,std::size_t maximum=16*1024*1024):scope_(scope),maximum_(maximum){if(maximum<4096||maximum>64*1024*1024)throw std::invalid_argument("Invalid host ledger size bound");scope_.prepare_private_directory();snapshot_=read();if(snapshot_){original_=Object::Parse(winrt::to_hstring(*snapshot_));structure(original_);if(text(original_,L"format",80)!="coincide.windows.background-host"||integer(original_,L"version")!=1||text(original_,L"scope",64)!=scope.id())throw std::runtime_error("Unsupported host ledger or physical data scope; the original was preserved");}else{original_=Object{};put(original_,L"format","coincide.windows.background-host");original_.SetNamedValue(L"version",Value::CreateNumberValue(1));put(original_,L"scope",scope.id());original_.SetNamedValue(L"sessions",Object{});original_.SetNamedValue(L"commands",Object{});}}
    Object copy()const{return Object::Parse(original_.Stringify());}
    void commit(Object next){scope_.verify();structure(next);auto bytes=winrt::to_string(next.Stringify());if(bytes.size()>maximum_)throw std::runtime_error("The durable host event ledger is full; persist and acknowledge events before accepting more work");if(read()!=snapshot_)throw std::runtime_error("The private runtime ledger changed outside this host; work requires review");std::optional<std::string> published(bytes);const auto temporary=scope_.ledger_directory()/winrt::to_hstring("runtime-"+new_guid()+".tmp").c_str();UserSecurity security(scope_.sid());Handle handle(CreateFileW(temporary.c_str(),GENERIC_WRITE|DELETE,FILE_SHARE_READ|FILE_SHARE_DELETE,&security.attributes,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr));if(!handle)throw std::runtime_error("Could not create the durable host checkpoint");struct Pending{HANDLE file;bool keep{};~Pending(){if(!keep){FILE_DISPOSITION_INFO remove{TRUE};SetFileInformationByHandle(file,FileDispositionInfo,&remove,sizeof(remove));}}}pending{handle.value};DWORD copied{};if(!WriteFile(handle.value,bytes.data(),static_cast<DWORD>(bytes.size()),&copied,nullptr)||copied!=bytes.size()||!FlushFileBuffers(handle.value)||!MoveFileExW(temporary.c_str(),file().c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))throw std::runtime_error("The host checkpoint did not persist; no completion was acknowledged");pending.keep=true;original_=std::move(next);snapshot_.swap(published);}
};
} // namespace coincide::background_host
